8fca55d1-680a-4f91-bcda-e524e9e54f52	78516af9-bd41-4d98-a553-f64dfa9eef5e	Standard Page Pattern - Quick Reference	<h1>Standard Page Pattern - Quick Reference</h1>\n<h2>Quick Start Template</h2>\n<pre><code class="language-tsx">&#39;use client&#39;;\n\nimport React, { useMemo } from &#39;react&#39;;\nimport { Box, Paper } from &#39;@mui/material&#39;;\nimport { Search } from &#39;@mui/icons-material&#39;;\nimport StandardCrudPageLayout from &#39;@/components/common/StandardCrudPageLayout&#39;;\nimport ExcelDataGrid from &#39;@/components/common/DataGrid&#39;;\nimport SearchFilterFields from &#39;@/components/common/SearchFilterFields&#39;;\nimport EmptyState from &#39;@/components/common/EmptyState&#39;;\nimport EditDrawer from &#39;@/components/common/EditDrawer&#39;;\nimport DeleteConfirmDialog from &#39;@/components/common/DeleteConfirmDialog&#39;;\nimport { useI18n, useCurrentLocale } from &#39;@/lib/i18n/client&#39;;\nimport { useYourPageManagement } from &#39;./hooks/useYourPageManagement&#39;;\nimport { createColumns } from &#39;./constants&#39;;\nimport { createFilterFields, calculateActiveFilterCount } from &#39;./utils&#39;;\nimport { YourEntity } from &#39;./types&#39;;\n\nexport default function YourPage() {\n  const t = useI18n();\n  const currentLocale = useCurrentLocale();\n\n  const {\n    // State\n    data,\n    searchCriteria,\n    quickSearch,\n    setQuickSearch,\n    paginationModel,\n    rowCount,\n    searching,\n    saveLoading,\n    dialogOpen,\n    editingItem,\n    setEditingItem,\n    advancedFilterOpen,\n    setAdvancedFilterOpen,\n    deleteConfirmOpen,\n    selectedForDelete,\n    deleteLoading,\n    helpOpen,\n    setHelpOpen,\n    helpExists,\n    isAdmin,\n    successMessage,\n    errorMessage,\n    // Handlers\n    handleAdd,\n    handleEdit,\n    handleSave,\n    handleDeleteClick,\n    handleDeleteConfirm,\n    handleDeleteCancel,\n    handleRefresh,\n    handleSearchChange,\n    handleQuickSearch,\n    handleQuickSearchClear,\n    handleAdvancedFilterApply,\n    handleAdvancedFilterClose,\n    handlePaginationModelChange,\n    setDialogOpen\n  } = useYourPageManagement();\n\n  const columns = useMemo(() =&gt; createColumns(t, handleEdit), [t, handleEdit]);\n  const filterFields = useMemo(() =&gt; createFilterFields(t), [t]);\n  const activeFilterCount = useMemo(\n    () =&gt; calculateActiveFilterCount(searchCriteria),\n    [searchCriteria]\n  );\n\n  return (\n    &lt;StandardCrudPageLayout\n      useMenu\n      showBreadcrumb\n      successMessage={successMessage}\n      errorMessage={errorMessage}\n      quickSearch={quickSearch}\n      onQuickSearchChange={setQuickSearch}\n      onQuickSearch={handleQuickSearch}\n      onQuickSearchClear={handleQuickSearchClear}\n      quickSearchPlaceholder=&quot;Search...&quot;\n      searching={searching}\n      showAdvancedFilter\n      advancedFilterOpen={advancedFilterOpen}\n      onAdvancedFilterClick={() =&gt; setAdvancedFilterOpen(!advancedFilterOpen)}\n      activeFilterCount={activeFilterCount}\n      filterTitle={`${t(&#39;common.search&#39;)} / ${t(&#39;common.filter&#39;)}`}\n      filterContent={\n        &lt;SearchFilterFields\n          fields={filterFields}\n          values={searchCriteria}\n          onChange={handleSearchChange}\n          onEnter={handleAdvancedFilterApply}\n        /&gt;\n      }\n      onFilterApply={handleAdvancedFilterApply}\n      onFilterClear={handleQuickSearchClear}\n      onFilterClose={handleAdvancedFilterClose}\n      programId=&quot;PROG-YOUR-PAGE&quot;\n      helpOpen={helpOpen}\n      onHelpOpenChange={setHelpOpen}\n      isAdmin={isAdmin}\n      helpExists={helpExists}\n      language={currentLocale}\n    &gt;\n      &lt;Paper sx={{ p: 1.5, flex: 1, display: &#39;flex&#39;, flexDirection: &#39;column&#39;, overflow: &#39;hidden&#39;, minHeight: 0 }}&gt;\n        {data.length === 0 &amp;&amp; !searching ? (\n          &lt;EmptyState\n            icon={Search}\n            title=&quot;No data loaded&quot;\n            description=&quot;Use the search filters above to find items&quot;\n          /&gt;\n        ) : (\n          &lt;Box sx={{ flex: 1, minHeight: 0 }}&gt;\n            &lt;ExcelDataGrid\n              rows={data}\n              columns={columns}\n              onRowsChange={(rows) =&gt; setData(rows as YourEntity[])}\n              onAdd={handleAdd}\n              onDelete={handleDeleteClick}\n              onRefresh={handleRefresh}\n              checkboxSelection\n              editable\n              exportFileName=&quot;your-data&quot;\n              loading={searching}\n              paginationMode=&quot;server&quot;\n              rowCount={rowCount}\n              paginationModel={paginationModel}\n              onPaginationModelChange={handlePaginationModelChange}\n            /&gt;\n          &lt;/Box&gt;\n        )}\n      &lt;/Paper&gt;\n\n      &lt;EditDrawer\n        open={dialogOpen}\n        onClose={() =&gt; {\n          setDialogOpen(false);\n          setEditingItem(null);\n        }}\n        title={!editingItem?.id ? &#39;Add New Item&#39; : &#39;Edit Item&#39;}\n        onSave={handleSave}\n        saveLoading={saveLoading}\n        saveLabel={t(&#39;common.save&#39;)}\n        cancelLabel={t(&#39;common.cancel&#39;)}\n      &gt;\n        {/* Your form fields here */}\n      &lt;/EditDrawer&gt;\n\n      &lt;DeleteConfirmDialog\n        open={deleteConfirmOpen}\n        itemCount={selectedForDelete.length}\n        itemName=&quot;item&quot;\n        itemsList={selectedForDelete.map(id =&gt; ({\n          id,\n          displayName: data.find(item =&gt; item.id === id)?.name || String(id)\n        }))}\n        onCancel={handleDeleteCancel}\n        onConfirm={handleDeleteConfirm}\n        loading={deleteLoading}\n      /&gt;\n    &lt;/StandardCrudPageLayout&gt;\n  );\n}\n</code></pre>\n<h2>File Structure Checklist</h2>\n<pre><code>your-page/\n├── ☐ page.tsx\n├── ☐ types.ts\n├── ☐ constants.tsx\n├── ☐ utils.ts\n└── hooks/\n    └── ☐ useYourPageManagement.ts\n</code></pre>\n<h2>types.ts Template</h2>\n<pre><code class="language-tsx">export interface YourEntity {\n  id: string;\n  name: string;\n  status: string;\n  // ... your fields\n}\n\nexport interface SearchCriteria {\n  name: string;\n  status: string;\n  // ... search fields\n  [key: string]: string | string[];\n}\n</code></pre>\n<h2>constants.tsx Template</h2>\n<pre><code class="language-tsx">import { GridColDef } from &#39;@mui/x-data-grid&#39;;\nimport ActionsCell from &#39;@/components/common/ActionsCell&#39;;\n\nexport const createColumns = (\n  t: any,\n  handleEdit: (id: string | number) =&gt; void\n): GridColDef[] =&gt; [\n  { field: &#39;id&#39;, headerName: &#39;ID&#39;, width: 70 },\n  { field: &#39;name&#39;, headerName: &#39;Name&#39;, width: 200 },\n  { field: &#39;status&#39;, headerName: &#39;Status&#39;, width: 120 },\n  {\n    field: &#39;actions&#39;,\n    headerName: &#39;Actions&#39;,\n    width: 80,\n    sortable: false,\n    filterable: false,\n    renderCell: (params) =&gt; (\n      &lt;ActionsCell\n        onEdit={() =&gt; handleEdit(params.row.id)}\n        showMore={false}\n      /&gt;\n    )\n  }\n];\n</code></pre>\n<h2>utils.ts Template</h2>\n<pre><code class="language-tsx">import { FilterFieldConfig } from &#39;@/components/common/SearchFilterFields&#39;;\nimport { SearchCriteria } from &#39;./types&#39;;\n\nexport const createFilterFields = (t: any): FilterFieldConfig[] =&gt; [\n  {\n    name: &#39;name&#39;,\n    label: &#39;Name&#39;,\n    type: &#39;text&#39;,\n    placeholder: &#39;Search by name...&#39;\n  },\n  {\n    name: &#39;status&#39;,\n    label: &#39;Status&#39;,\n    type: &#39;select&#39;,\n    options: [\n      { value: &#39;&#39;, label: &#39;All&#39; },\n      { value: &#39;active&#39;, label: &#39;Active&#39; },\n      { value: &#39;inactive&#39;, label: &#39;Inactive&#39; }\n    ]\n  }\n];\n\nexport const calculateActiveFilterCount = (searchCriteria: SearchCriteria): number =&gt; {\n  return Object.entries(searchCriteria).filter(([_key, value]) =&gt; {\n    if (Array.isArray(value)) return value.length &gt; 0;\n    return value !== &#39;&#39;;\n  }).length;\n};\n</code></pre>\n<h2>useYourPageManagement.ts Template</h2>\n<pre><code class="language-tsx">import { useState, useCallback } from &#39;react&#39;;\nimport { api } from &#39;@/lib/axios&#39;;\nimport { usePageState } from &#39;@/hooks/usePageState&#39;;\nimport { useAutoHideMessage } from &#39;@/hooks/useAutoHideMessage&#39;;\nimport { YourEntity, SearchCriteria } from &#39;../types&#39;;\n\nexport const useYourPageManagement = () =&gt; {\n  const {\n    searchCriteria,\n    setSearchCriteria,\n    paginationModel,\n    setPaginationModel,\n    quickSearch,\n    setQuickSearch,\n    data,\n    setData,\n    rowCount,\n    setRowCount\n  } = usePageState&lt;SearchCriteria, YourEntity&gt;({\n    storageKey: &#39;your-page-state&#39;,\n    initialCriteria: {\n      name: &#39;&#39;,\n      status: &#39;&#39;\n    },\n    initialPaginationModel: {\n      page: 0,\n      pageSize: 50\n    }\n  });\n\n  const { successMessage, errorMessage, showSuccess, showError } = useAutoHideMessage();\n\n  const [searching, setSearching] = useState(false);\n  const [saveLoading, setSaveLoading] = useState(false);\n  const [dialogOpen, setDialogOpen] = useState(false);\n  const [editingItem, setEditingItem] = useState&lt;YourEntity | null&gt;(null);\n  const [advancedFilterOpen, setAdvancedFilterOpen] = useState(false);\n  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);\n  const [selectedForDelete, setSelectedForDelete] = useState&lt;(string | number)[]&gt;([]);\n  const [deleteLoading, setDeleteLoading] = useState(false);\n  const [helpOpen, setHelpOpen] = useState(false);\n  const [helpExists, setHelpExists] = useState(false);\n  const [isAdmin, setIsAdmin] = useState(false);\n\n  // Implement your handlers here...\n\n  return {\n    // State\n    data,\n    setData,\n    searchCriteria,\n    quickSearch,\n    setQuickSearch,\n    paginationModel,\n    rowCount,\n    searching,\n    saveLoading,\n    dialogOpen,\n    editingItem,\n    setEditingItem,\n    advancedFilterOpen,\n    setAdvancedFilterOpen,\n    deleteConfirmOpen,\n    selectedForDelete,\n    deleteLoading,\n    helpOpen,\n    setHelpOpen,\n    helpExists,\n    isAdmin,\n    successMessage,\n    errorMessage,\n    showError,\n    // Handlers\n    handleAdd: () =&gt; {},\n    handleEdit: (id: string | number) =&gt; {},\n    handleSave: async () =&gt; {},\n    handleDeleteClick: (ids: (string | number)[]) =&gt; {},\n    handleDeleteConfirm: async () =&gt; {},\n    handleDeleteCancel: () =&gt; {},\n    handleRefresh: () =&gt; {},\n    handleSearchChange: (field: keyof SearchCriteria, value: string | string[]) =&gt; {},\n    handleQuickSearch: () =&gt; {},\n    handleQuickSearchClear: () =&gt; {},\n    handleAdvancedFilterApply: () =&gt; {},\n    handleAdvancedFilterClose: () =&gt; {},\n    handlePaginationModelChange: (newModel: { page: number; pageSize: number }) =&gt; {},\n    setDialogOpen\n  };\n};\n</code></pre>\n<h2>Key Components Reference</h2>\n<h3>StandardCrudPageLayout</h3>\n<p>Main layout wrapper for CRUD pages.</p>\n<p><strong>Required Props:</strong></p>\n<ul>\n<li><code>quickSearch</code>, <code>onQuickSearchChange</code>, <code>onQuickSearch</code>, <code>onQuickSearchClear</code></li>\n<li><code>children</code></li>\n</ul>\n<p><strong>Optional Props:</strong></p>\n<ul>\n<li>All other props for customization</li>\n</ul>\n<h3>MessageAlert</h3>\n<p>Auto-hiding alert messages.</p>\n<p><strong>Props:</strong></p>\n<ul>\n<li><code>successMessage</code>, <code>errorMessage</code>, <code>warningMessage</code>, <code>infoMessage</code></li>\n</ul>\n<h3>ExcelDataGrid</h3>\n<p>Advanced data grid with CRUD operations.</p>\n<p><strong>Key Props:</strong></p>\n<ul>\n<li><code>rows</code>, <code>columns</code></li>\n<li><code>onAdd</code>, <code>onDelete</code>, <code>onRefresh</code></li>\n<li><code>paginationMode=&quot;server&quot;</code>, <code>rowCount</code>, <code>paginationModel</code></li>\n</ul>\n<h2>Common Hooks</h2>\n<pre><code class="language-tsx">// Page state with persistence\nusePageState&lt;SearchCriteria, YourEntity&gt;({ ... })\n\n// Auto-hide messages\nuseAutoHideMessage({ duration: 10000 })\n\n// Internationalization\nuseI18n()\nuseCurrentLocale()\n</code></pre>\n<h2>Reference</h2>\n<p>See full documentation: <a href="./STANDARD_PAGE_PATTERN.md">STANDARD_PAGE_PATTERN.md</a></p>\n<p>See working example: <a href="../src/app/%5Blocale%5D/admin/users/page.tsx"><code>src/app/[locale]/admin/users/page.tsx</code></a></p>\n	1	관리자	IT	f	normal	published	f	\N	f	t	\N	\N	0	0	0	0	[]	{}	'../types':524B './constants':66B './hooks/useyourpagemanagement':62B './types':75B,445B './utils':71B '/admin/users/page.tsx':765B '/box':282B '/components/common/actionscell':388B '/components/common/datagrid':37B '/components/common/deleteconfirmdialog':53B '/components/common/editdrawer':49B '/components/common/emptystate':45B '/components/common/searchfilterfields':41B,441B '/components/common/standardcrudpagelayout':33B '/editdrawer':314B '/hooks/useautohidemessage':519B '/hooks/usepagestate':515B '/lib/axios':511B '/lib/i18n/client':58B '/paper':283B '/standardcrudpagelayout':340B '0':223B,225B,248B,497B,552B '1':215B,246B '1.5':213B '10000':751B '120':417B '200':411B '50':554B '70':405B '80':423B 'action':419B,421B 'actionscel':386B,430B 'activ':473B,475B 'activefiltercount':141B,172B,173B 'add':295B 'advanc':719B 'advancedfilteropen':99B,167B,168B,171B,584B,637B 'alert':711B 'api':509B 'array.isarray':493B 'async':656B,662B 'auto':709B,746B 'auto-hid':708B,745B 'box':22B,243B 'calculateactivefiltercount':69B,143B,482B 'cancellabel':307B 'checkboxselect':266B 'checklist':343B 'children':699B 'client':15B 'column':127B,219B,252B,253B,728B 'common':736B 'common.cancel':309B 'common.filter':178B 'common.save':306B 'common.search':176B 'compon':684B 'const':80